IF jsonb_array_length(docs)<>jsonb_array_length(p_request->'sourceDocumentIds') THEN RAISE EXCEPTION 'input_preparation_source_missing'; END IF;
IF jsonb_array_length(docs)>0 THEN
 -- Exact existing-seal lookup under the shared source fence; full receipt is charged only when new.
 SELECT jsonb_agg(jsonb_build_object('id',d.id::text,'rowHash',encode(sha256(convert_to(to_jsonb(d)::text,'UTF8')),'hex'),
  'root',public.research_source_root_v2(to_jsonb(d)),'publishedAt',to_jsonb(d)->'published_at',
  'observedAt',to_jsonb(d)->'collected_at','rights',d.metadata->>'rights_boundary') ORDER BY d.id) INTO seal_manifest
  FROM public.source_raw_documents d WHERE p_request->'sourceDocumentIds' @> jsonb_build_array(d.id::text);
 seal_hash:=encode(sha256(convert_to(jsonb_build_object('documents',seal_manifest,'cutoff',n)::text,'UTF8')),'hex');
 new_seal:=NOT EXISTS(SELECT FROM public.research_source_seals_v2 WHERE request_hash=seal_hash);
 seal:=public.seal_research_sources_v2(docs,n);
 IF seal->>'request_hash' IS DISTINCT FROM seal_hash THEN RAISE EXCEPTION 'input_preparation_seal_projection_changed'; END IF;
END IF;
-- Freeze DB-derived manifests; full original rows remain behind the private source seal.
-- No supplied model output, financial facts, calculator or role identity is accepted here.
material:=jsonb_build_object('schemaVersion','research-input-preparation-v2','researchCompanyId',j.research_company_id,'symbol',j.symbol,
 'scope',j.research_scope,'snapshotHash',snap.snapshot_hash,'mappingDigest',snap.mapping_digest,'stockId',j.stock_id,
 'priorityRunId',pri.run_id,'priorityInputHash',pri.input_hash,'discoveryCutoff',pri.as_of,'originalModelCutoff',NULL,'researchCutoff',n,
 'originalJob',jsonb_build_object('jobId',j.job_id,'attempt',j.attempts,'owner',j.lease_owner,'leaseExpiresAt',j.lease_expires_at),
 'originalReservation',jsonb_build_object('reservationId',r.reservation_id,'startedAt',r.started_at,'leaseExpiresAt',r.lease_expires_at),
 'sourceManifest',coalesce(seal->'documents','[]'),'sourceSelectionComplete',false,'financial',NULL,'calculator',NULL,
 'status','draft_incomplete','gaps',jsonb_build_array('financial_input_revision_missing','trusted_calculator_not_bound','original_model_not_selected','trusted_execution_authority_unavailable')||CASE WHEN jsonb_array_length(docs)=0 THEN jsonb_build_array('sources_not_selected') ELSE '[]'::jsonb END,
 'modelDispatched',false,'publishableResearch',false,'researchQualified',false,'strategyApproved',false,'entryEligible',false);
charged_bytes:=public.research_input_preparation_bytes_v2(p_request,material,CASE WHEN new_seal THEN seal ELSE 'null'::jsonb END);
IF used_bytes+charged_bytes>524288 THEN RAISE EXCEPTION 'input_preparation_byte_bound'; END IF;

'preparation',jsonb_build_object('id',parent->'preparation_id','inputHash',parent->'input_hash'),
'researchIdentity',jsonb_build_object('researchCompanyId',p->'researchCompanyId','symbol',p->'symbol','scope',p->'scope','snapshotHash',p->'snapshotHash','mappingDigest',p->'mappingDigest','stockId',p->'stockId'),
'priority',jsonb_build_object('runId',p->'priorityRunId','inputHash',p->'priorityInputHash','discoveryCutoff',p->'discoveryCutoff'),
'originalJob',p->'originalJob','originalReservation',p->'originalReservation','sources',jsonb_build_object('sealId',parent->'source_seal_id','manifest',p->'sourceManifest','coverage','incomplete'),
'financial',jsonb_build_object('artifactInventory',m->'inventory','material',f)||CASE WHEN c->>'wireVersion'='research-article-input-v3' THEN jsonb_build_object('candidate',p_calculation-'financialMaterial','protocol',c||jsonb_build_object('bindingCapsuleIdentity',b->>'bindingCapsuleIdentity')) ELSE '{}'::jsonb END,
'hashes',jsonb_build_object('preparationInputHash',parent->'input_hash','artifactInventoryHash',public.research_complete_hash_v2(m->'inventory'),'modelHistoricalCanonicalHash',m->'historicalHash',
'sourceManifestHash',public.research_complete_hash_v2(projection->'sourceManifest'),'projectionHash',public.research_complete_hash_v2(projection),'scenarioInputHash',public.research_complete_hash_v2(projection->'projected'->'scenarios'),'resultHash',public.research_complete_hash_v2(calc),'sourceClosureHash',c->'sourceExecutionHash'),
'clocks',jsonb_build_object('originalModelCutoff',m->'modelCutoff','originalPreparationAdmittedAt',parent->'admitted_at','artifactReadKnownAt',p_calculation->'artifactReadKnownAt','financialAdmittedAt',n,'researchCutoff',n),
'gaps',gaps,'capabilities',jsonb_build_object('financialVerified',false,'dispatchReady',false,'modelDispatched',false,'publishableResearch',false,'researchQualified',false,'strategyApproved',false,'entryEligible',false,'historicalPITEligible',false));
charge:=octet_length(convert_to(public.research_complete_canonical_v2(p_request),'UTF8'))+octet_length(convert_to(public.research_complete_canonical_v2(material),'UTF8'));
SELECT count(*),coalesce(sum(logical_bytes),0) INTO used_count,used_bytes FROM (
SELECT logical_bytes FROM public.research_input_preparations_v2 WHERE job_id=(parent->>'job_id')::uuid AND attempt=(parent->>'attempt')::int AND reservation_id=(parent->>'reservation_id')::uuid
UNION ALL SELECT logical_bytes FROM public.research_article_input_revisions_v2 WHERE job_id=(parent->>'job_id')::uuid AND attempt=(parent->>'attempt')::int AND reservation_id=(parent->>'reservation_id')::uuid) history;
IF used_count>=4 THEN RAISE EXCEPTION 'complete_count_bound';END IF;IF used_bytes+charge>524288 THEN RAISE EXCEPTION 'complete_byte_bound';END IF;
IF clock_timestamp()>=least((p->'originalJob'->>'leaseExpiresAt')::timestamptz,(p->'originalReservation'->>'leaseExpiresAt')::timestamptz) THEN RAISE EXCEPTION 'complete_lease_lost';END IF;
rh:=public.research_complete_hash_v2(p_request);ih:=public.research_complete_hash_v2(material);
INSERT INTO public.research_article_input_revisions_v2(preparation_id,job_id,attempt,reservation_id,research_company_id,research_scope,snapshot_hash,request_hash,canonical_request,input_hash,canonical_payload,logical_bytes,admitted_at,research_cutoff,source_seal_id)
VALUES((parent->>'preparation_id')::uuid,(parent->>'job_id')::uuid,(parent->>'attempt')::int,(parent->>'reservation_id')::uuid,(p->>'researchCompanyId')::uuid,'research_observed_v1',p->>'snapshotHash',rh,p_request,ih,material,charge,n,n,(parent->>'source_seal_id')::uuid) RETURNING * INTO saved;

IF NULLIF(doc->'metadata'->>'parent_source_url','') IS NOT NULL
 AND doc->'metadata'->>'parent_source_url' IS DISTINCT FROM COALESCE(NULLIF(doc->'metadata'->>'canonical_url',''),split_part(doc->>'document_url','#si-revision-',1)) THEN RAISE EXCEPTION 'source_seal_unsupported_parent_lineage'; END IF;
IF octet_length(doc::text)>4194304 THEN RAISE EXCEPTION 'source_seal_document_bound'; END IF;
row_hash:=encode(sha256(convert_to(doc::text,'UTF8')),'hex'); root:=public.research_source_root_v2(doc);
IF row_hash<>item->>'rowHash' THEN RAISE EXCEPTION 'source_seal_hash_changed'; END IF;
IF root IS NULL OR root='' OR octet_length(root)>4096 OR (doc->>'collected_at')::timestamptz IS NULL
 OR NOT isfinite((doc->>'collected_at')::timestamptz) OR (doc->>'collected_at')::timestamptz>p_cutoff
 OR (doc->>'published_at')::timestamptz>p_cutoff THEN RAISE EXCEPTION 'source_seal_clock'; END IF;
IF COALESCE(doc->'metadata'->>'rights_boundary','') NOT IN ('public_citation','bounded_summary_only')
 OR NULLIF(doc->'metadata'->>'retracted_at','') IS NOT NULL OR doc->'metadata'->>'claim_status'='denied' THEN RAISE EXCEPTION 'source_seal_rights_or_withdrawn'; END IF;
